/**
 * @file main.c
 * @brief Application entry point and cooperative superloop
 * @author Embedded Systems Team
 * @license MIT
 *
 * ARCHITECTURE NOTE:
 * - [CUBEMX GENERATED]:
 *     SystemClock_Config, MX_GPIO_Init, MX_I2C1_Init, MX_USART1_UART_Init, MX_USART2_UART_Init.
 *     These peripheral initialization routines are declared here as extern functions
 *     and MUST be generated by STM32CubeMX using piano_hand.ioc once the board
 *     pinout is finalized. They are NOT implemented in this hand-written file.
 *
 * - [HAND-WRITTEN]:
 *     main() entry point, peripheral handle registration, Piano Hand controller PH_Init(),
 *     and the non-blocking superloop calling PH_Update().
 */

#include "main.h"
#include "piano_hand.h"

/* ============================================================================
 * CubeMX-Generated Hardware Handles (Instantiated in CubeMX-generated files)
 * ============================================================================ */
I2C_HandleTypeDef  hi2c1;
UART_HandleTypeDef huart1;
UART_HandleTypeDef huart2;

/* ============================================================================
 * CubeMX-Generated Initialization Functions (Extern Declarations)
 * ============================================================================ */
extern void SystemClock_Config(void);
extern void MX_GPIO_Init(void);
extern void MX_I2C1_Init(void);
extern void MX_USART1_UART_Init(void);
extern void MX_USART2_UART_Init(void);

/* ============================================================================
 * Application Entry Point
 * ============================================================================ */
int main(void)
{
    /* Reset of all peripherals, Initializes the Flash interface and the Systick. */
    HAL_Init();

    /* Configure the system clock (180 MHz for STM32F446RE) */
    SystemClock_Config();

    /* Initialize all configured peripherals */
    MX_GPIO_Init();
    MX_I2C1_Init();
    MX_USART1_UART_Init();
    MX_USART2_UART_Init();

    /* Prepare hardware handle mapping for Piano Hand Application Controller */
    PH_HardwareHandles_t hw;
    hw.i2c_handle   = &hi2c1;   /* PCA9685 PWM driver on I2C1 */
    hw.uart_stepper = &huart1;  /* Stepper motor driver on USART1 (115200 baud) */
    hw.uart_comms   = &huart2;  /* Host communication / USB VCP on USART2 (115200 baud) */
    hw.tim_encoder  = NULL;     /* Encoder disabled (ENCODER_ENABLED=0) */

    /* Initialize Piano Hand application */
    PH_Init(&hw);

    /* Cooperative non-blocking superloop */
    while (1) {
        uint32_t now = HAL_GetTick();
        PH_Update(now);
    }
}

/**
 * @brief  This function is executed in case of error occurrence.
 */
void Error_Handler(void)
{
    __disable_irq();
    while (1) {
    }
}
